  package   org . jinstagram . utils ;   import    com . google . gson . Gson ;  import    com . google . gson . GsonBuilder ;  import    com . google . gson . JsonElement ;  import    com . google . gson . JsonParser ;  import   org . slf4j . Logger ;   public final class LogHelper  {   private static final String  EXCEPTION_PATTERN =  "Error in method {0}.\n\tException name: {1}.\n\t" + "Stack trace: {2}.\n\tTime spent in the method: {3} milliseconds." ;   private static final String  EXIT_METHOD_PATTERN =  "Exiting method %s.\n\tReturn value: [{%s}].\n\tTime spent in the method: {2" + "%d} milliseconds." ;   private static final String  ENTRANCE_METHOD_PATTERN = "Entering method %s.\n\tMethod arguments: [%s]." ;   private static Gson  GSON =    new GsonBuilder  ( ) . setPrettyPrinting  ( ) . create  ( ) ;   private LogHelper  ( )  { }   public static void logEntrance  (  Logger logger ,  String methodName ,  String methodArguments )  {   logger . debug  (  String . format  ( ENTRANCE_METHOD_PATTERN , methodName , methodArguments ) ) ; }   public static void prettyPrintJSONResponse  (  Logger logger ,  String jsonString )  {  if  (  logger . isDebugEnabled  ( ) )  {  String  s ;  try  {   final JsonElement  element =   new JsonParser  ( ) . parse  ( jsonString ) ;   s =     new GsonBuilder  ( ) . setPrettyPrinting  ( ) . create  ( ) . toJson  ( element ) ; }  catch (   Exception e )  {   s = jsonString ; }   logger . debug  (  "Received JSON response from Instagram - " + s ) ; } }   public static void logExit  (  Logger logger ,  String methodName ,  String returnValue ,   long timeSpent )  {   logger . debug  (  String . format  ( EXIT_METHOD_PATTERN , methodName , returnValue , timeSpent ) ) ; }   public static void logException  (  Logger logger ,  String methodName ,  Throwable e ,   long timeSpent )  {   logger . error  (  String . format  ( EXCEPTION_PATTERN , methodName ,   e . getClass  ( ) . getSimpleName  ( ) ,  e . getMessage  ( ) ) ) ; } }